      expect(result.warnings).toContain('Found 2 potential duplicates (similar description/weight/brand)')
    })

    it('should return no duplicates for unique items', () => {
      const items = [
        {
          description: 'Tent',
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        },
        {
          description: 'Sleeping Bag',
          weight_g: 800,
          item_type: 'Sleep',
          consumable: false
        },
        {
          description: 'Stove',
          weight_g: 200,
          item_type: 'Cook',
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(3)
      expect(result.duplicates).toHaveLength(0)
      expect(result.warnings).toHaveLength(0)
    })
  })
})

