import { 
  type ParsedGearItem, 
  type GearParseResult, 
  parseWeightFromText, 
  parseBoolean, 
  validateParsedGearItem 
} from './index'

export function parseLighterPackHtml(html: string): GearParseResult {
  const result: GearParseResult = {
    success: false,
    data: [],
    errors: [],
    warnings: [],
    metadata: {}
  }

  try {
    // Extract list name from title or h1
    const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i) || 
                      html.match(/<h1[^>]*>([^<]+)<\/h1>/i)

    if (titleMatch) {
      result.metadata.listName = titleMatch[1].replace(/\s*-\s*LighterPack.*$/i, '').trim()
    }

    // Look for lpCategories unordered list
    const categoriesMatch = html.match(/<ul[^>]*class="[^"]*lpCategories[^"]*"[^>]*>(.*?)<\/ul>/gis)

    if (!categoriesMatch || categoriesMatch.length === 0) {
      result.errors.push('No lpCategories unordered list found')
      return result
    }

    // Parse each category list
    for (const categoryHtml of categoriesMatch) {
      // Extract individual lpItems from this category
      const itemMatches = categoryHtml.match(/<li[^>]*class="[^"]*lpItem[^"]*"[^>]*>.*?<\/li>/gis)

      if (itemMatches) {
        for (const itemHtml of itemMatches) {
          try {
            const item = parseHtmlItem(itemHtml)
            if (item) {
              const validationErrors = validateParsedGearItem(item)
              if (validationErrors.length === 0) {
                result.data.push(item)
              } else {
                result.errors.push(`Invalid item: ${validationErrors.join(', ')}`)
              }
            }
          } catch (error) {
            const message = error instanceof Error ? error.message : 'Unknown error'
            result.warnings.push(`Failed to parse item: ${message}`)
          }
        }
      }
    }

    // Calculate metadata
    if (result.data.length > 0) {
      result.metadata.totalWeight = result.data.reduce((sum, item) => sum + item.weight_g, 0)
      result.metadata.itemCount = result.data.length
    }

    result.success = result.data.length > 0

    if (result.data.length === 0) {
      result.errors.push('No gear items found in the LighterPack page')
    }

    return result

  } catch (error) {
    result.errors.push(error instanceof Error ? error.message : 'Unknown parsing error')
    return result
  }
}

function parseHtmlItem(itemHtml: string): ParsedGearItem | null {
  try {
    // Extract name (item_type) from lpName span
    const nameMatch = itemHtml.match(/<span[^>]*class="[^"]*lpName[^"]*"[^>]*>([^<]+)<\/span>/i)
    const name = nameMatch?.[1]?.trim()

    if (!name) return null

    // Extract description from lpDesc span, or anchor text within lpName
    let description = name // fallback to name

    // Try to get description from lpDesc
    const descMatch = itemHtml.match(/<span[^>]*class="[^"]*lpDesc[^"]*"[^>]*>([^<]+)<\/span>/i)
    if (descMatch?.[1]?.trim()) {
      description = descMatch[1].trim()
    } else {
      // Try to get from anchor text in lpName
      const anchorMatch = itemHtml.match(/<a[^>]*>([^<]+)<\/a>/i)
      if (anchorMatch?.[1]?.trim() && anchorMatch[1].trim() !== name) {
        description = anchorMatch[1].trim()
      }
    }

    // Extract URL from anchor in lpName
    const urlMatch = itemHtml.match(/<a[^>]*href="([^"]+)"/i)
    const url = urlMatch?.[1] || null

    // Extract weight and unit from lpWeight span and lpUnitSelect
    const weightMatch = itemHtml.match(/<span[^>]*class="[^"]*lpWeight[^"]*"[^>]*>([^<]+)<\/span>/i)
    if (!weightMatch) return null

    const unitMatch = itemHtml.match(/<span[^>]*class="[^"]*lpDisplay[^"]*"[^>]*>([^<]+)<\/span>/i)
    const unit = unitMatch?.[1]?.trim() || 'g'

    const weight = parseFloat(weightMatch[1])
    if (isNaN(weight)) return null

    // Convert to grams based on unit
    let weight_g: number
    switch (unit.toLowerCase()) {
      case 'oz':
        weight_g = Math.round(weight * 28.3495)
        break
      case 'lb':
        weight_g = Math.round(weight * 453.592)
        break
      case 'kg':
