const COLUMN_MAPPINGS = {
  description: ['name', 'item name', 'item', 'gear name', 'product', 'label', 'description'],
  brand: ['brand', 'manufacturer', 'make'],
  weight: ['weight', 'weight (g)', 'weight (grams)', 'weight_grams', 'wt', 'oz', 'grams'],
  item_type: ['category', 'type', 'gear type', 'class', 'item_type'],
  consumable: ['consumable', 'consumables', 'is consumable'],
  price: ['price', 'cost', 'msrp', 'value'],
  notes: ['notes', 'note', 'comments'],
  url: ['url', 'link', 'product url', 'website']
}

export function parseCsv(csvContent: string): GearParseResult {
  const result: GearParseResult = {
    success: false,
    data: [],
    errors: [],
    warnings: []
  }

  try {
    const lines = csvContent.trim().split('\n')
    if (lines.length < 2) {
      result.errors.push('CSV must have at least a header row and one data row')
      return result
    }

    const headers = parseRow(lines[0])
    const allParsedRows = lines.slice(1).map(line => parseRow(line))

    // Create column mapping with intelligent detection
    const columnMap = mapColumns(headers, allParsedRows)

    if (columnMap.description === undefined) {
      result.success = false
      result.errors.push('No description/item column found. Required columns: description, weight')
      return result
    }

    if (columnMap.weight === undefined) {
      result.success = false
      result.errors.push('No weight column found. Required columns: description, weight')
      return result
    }

    // Parse each row
    for (let i = 0; i < allParsedRows.length; i++) {
      const row = allParsedRows[i]
      if (row.length === 0 || row.every(cell => !cell.trim())) continue

      try {
        const item = parseRowToGearItem(row, columnMap, headers)
        const validationErrors = validateParsedGearItem(item)

        if (validationErrors.length > 0) {
          result.errors.push(`Row ${i + 2}: ${validationErrors.join(', ')}`)
          continue
        }

        result.data.push(item)
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Unknown error'
        result.errors.push(`Row ${i + 2}: ${message}`)
      }
    }

    // Check for duplicates within the parsed data
    const { unique, duplicates } = findDuplicates(result.data)
    result.data = unique

    if (duplicates.length > 0) {
      result.warnings.push(`Found ${duplicates.length} potential duplicate${duplicates.length === 1 ? '' : 's'} (similar description/weight/brand)`)
    }

    result.success = result.data.length > 0
    return result

  } catch (error) {
    result.errors.push(error instanceof Error ? error.message : 'Unknown parsing error')
    return result
  }
}

function parseRow(line: string): string[] {
  const result: string[] = []
  let current = ''
  let inQuotes = false
  let i = 0

  while (i < line.length) {
    const char = line[i]

    if (char === '"') {
      if (inQuotes && line[i + 1] === '"') {
        current += '"'
        i += 2
        continue
      }
      inQuotes = !inQuotes
    } else if (char === ',' && !inQuotes) {
      result.push(current.trim())
      current = ''
    } else {
      current += char
    }
    i++
  }

  result.push(current.trim())
  return result
}

function mapColumns(headers: string[], rows: string[][]): ColumnMap {
  const map: ColumnMap = {}

  for (const [field, possibleNames] of Object.entries(COLUMN_MAPPINGS)) {
    for (let i = 0; i < headers.length; i++) {
      const header = headers[i].toLowerCase().trim()
      if (possibleNames.some(name => header.includes(name.toLowerCase()))) {
        map[field] = i
        break
      }
    }
  }

  return map
}

function parseRowToGearItem(values: string[], columnMap: ColumnMap, headers: string[]): ParsedGearItem {
  const getValue = (field: string): string => {
    const index = columnMap[field]
    return index !== undefined ? values[index]?.trim() || '' : ''
  }

  // Check column structure for smart mapping
  const hasNameColumn = headers.some(h => ['name', 'item name', 'item', 'gear name', 'product', 'label'].includes(h.toLowerCase().trim()))
  const hasDescColumn = headers.some(h => ['description'].includes(h.toLowerCase().trim()))

  // Required fields
  const description = getValue('description')
  if (!description) {
    throw new Error('Item description is required')
  }

  const weightStr = getValue('weight')
  if (!weightStr) {
    throw new Error('Weight is required')
  }

  const { grams: weight_g, unit: weight_unit_display } = parseWeightFromText(weightStr)

  // Optional fields with fallbacks
  let brand = getValue('brand') || undefined
  let item_type = getValue('item_type') || 'Other'

  // Try to detect brand from description if not provided
  if (!brand) {
    brand = detectBrand(description)
  }

  // Also try to detect brand from description column in CSV if we have separate name and description
  if (!brand && hasNameColumn && hasDescColumn) {
    const descContent = headers.map((h, i) => h.toLowerCase().trim() === 'description' ? values[i]?.trim() : null).find(v => v)
    if (descContent) {
      brand = detectBrand(descContent)
    }
  }

  // Keep item_type as provided in CSV, no automatic categorization

  const consumable = parseBoolean(getValue('consumable'))
  const priceStr = getValue('price')
  const price = priceStr ? parseFloat(priceStr.replace(/[$,]/g, '')) : undefined
  // Smart notes handling: 
  // If we have both name and description columns, put description content in notes
  // If we only have description column, it's already used as main description
  let notes = getValue('notes') || undefined

  if (!notes && hasNameColumn && hasDescColumn) {
    // We have separate name and description columns, so put description in notes
    notes = headers.map((h, i) => h.toLowerCase().trim() === 'description' ? values[i]?.trim() : null).find(v => v) || undefined
  }
  const url = getValue('url') || undefined

  return {
    description,
    brand: brand || null,
    model: null, // CSV rarely has model info separate from description
    weight_g,
    weight_unit_display,
    item_type,
    consumable,
    price: price || null,
    notes: notes || null,
    image_url: null, // CSV doesn't contain images
    url: url || null
  }
}

function findDuplicates(items: ParsedGearItem[]): { unique: ParsedGearItem[], duplicates: { item: ParsedGearItem, duplicateOf: number }[] } {
  const unique: ParsedGearItem[] = []
  const duplicates: { item: ParsedGearItem, duplicateOf: number }[] = []

  for (let i = 0; i < items.length; i++) {
    const currentItem = items[i]
    let isDuplicate = false

    for (let j = 0; j < unique.length; j++) {
      const existingItem = unique[j]

      // Check if descriptions match (case-insensitive)
      const descriptionsMatch = currentItem.description.toLowerCase().trim() === existingItem.description.toLowerCase().trim()

      // Check if weights are similar (within 5g)
      const weightsMatch = Math.abs(currentItem.weight_g - existingItem.weight_g) <= 5

      // Check if brands match (case-insensitive, treating null/undefined as empty)
      const brandsMatch = (currentItem.brand || '').toLowerCase().trim() === (existingItem.brand || '').toLowerCase().trim()

      if (descriptionsMatch && weightsMatch && brandsMatch) {
        duplicates.push({ item: currentItem, duplicateOf: j })
        isDuplicate = true
        break
      }
    }

    if (!isDuplicate) {
      unique.push(currentItem)
    }
  }

  return { unique, duplicates }
}

import { describe, it, expect } from 'vitest'
import { parseCsv } from './csv'
import { validateGearItems, checkForDuplicates } from './index'

describe('CSV Parser', () => {
  describe('parseCsv', () => {
    it('should parse basic CSV with required fields', () => {
      const csv = `name,weight,category
Tent,1200g,Shelter
Sleeping Bag,800g,Sleep System`

      const result = parseCsv(csv)

      // Debug output
      if (!result.success) {
        console.log('Parse result:', result)
      }

      expect(result.success).toBe(true)
      expect(result.data).toHaveLength(2)
      expect(result.errors).toHaveLength(0)

      expect(result.data[0]).toMatchObject({
        description: 'Tent',
        weight_g: 1200,
        item_type: 'Shelter',
        consumable: false
      })
    })

    it('should handle different weight units', () => {
      const csv = `name,weight
Item1,2.5oz
Item2,1200g
Item3,1.5 oz`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].weight_g).toBeCloseTo(71, 0) // 2.5oz ≈ 71g
      expect(result.data[1].weight_g).toBe(1200)
      expect(result.data[2].weight_g).toBeCloseTo(43, 0) // 1.5oz ≈ 43g
    })

    it('should handle quoted fields with commas', () => {
      const csv = `name,weight,description
"Tent, 2-person",1200g,"Lightweight, waterproof"
Stove,150g,"Compact, efficient"`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].description).toBe('Tent, 2-person')
      expect(result.data[0].notes).toBe('Lightweight, waterproof')
    })

    it('should handle flexible column naming', () => {
      const csv = `Item Name,Weight (g),Gear Type,Qty,Brand
Ultralight Tent,1000,Shelter,1,Zpacks
Water Bottle,100,Water,2,Nalgene`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data).toHaveLength(2)
      expect(result.data[0]).toMatchObject({
        description: 'Ultralight Tent',
        weight_g: 1000,
        item_type: 'Shelter',
        brand: 'Zpacks'
      })
    })

    it('should handle boolean fields', () => {
      const csv = `name,weight,worn,consumable
Base Layer,200g,true,false
Energy Bar,50g,no,yes`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].consumable).toBe(false)
      expect(result.data[1].consumable).toBe(true)
    })

    it('should handle price parsing', () => {
      const csv = `name,weight,price
Tent,1200g,$299.99
Stove,150g,89.50`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].price).toBe(299.99)
      expect(result.data[1].price).toBe(89.50)
    })

    it('should fail with missing required columns', () => {
      const csv = `description,color
Nice tent,Blue`

      const result = parseCsv(csv)

      expect(result.success).toBe(false)
      expect(result.errors).toContain('No weight column found. Required columns: description, weight')
    })

    it('should handle empty rows and malformed data gracefully', () => {
      const csv = `name,weight,category
Tent,1200g,Shelter

,invalid,
Good Item,500g,Other`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data).toHaveLength(2) // Should skip empty/invalid rows
      expect(result.data[0].description).toBe('Tent')
      expect(result.data[1].description).toBe('Good Item')
    })

    it('should provide detailed error messages for invalid rows', () => {
      const csv = `name,weight
,200g
ValidItem,invalid_weight`

      const result = parseCsv(csv)

      expect(result.errors.length).toBeGreaterThan(0)
      expect(result.errors.some(e => e.includes('Item description is required'))).toBe(true)
    })


    it('should extract brand information from descriptions', () => {
      const csv = `name,weight,description
Ultralight Tent,1000g,zpacks duplex ultralight
Water Filter,50g,sawyer mini portable
Headlamp,80g,petzl actik rechargeable`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].brand).toBe('Zpacks')
      expect(result.data[1].brand).toBe('Sawyer')
      expect(result.data[2].brand).toBe('Petzl')
    })

    it('should handle mixed usage patterns intelligently', () => {
      const csv = `name,weight,description,notes
Base Layer,200g,patagonia merino,warm and comfortable
Sleeping Pad,400g,sleep,r-value 4.5
Cook Pot,150g,cooking gear,titanium construction`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].brand).toBe('Patagonia')
      expect(result.data[0].notes).toBe('warm and comfortable')
      expect(result.data[1].item_type).toBe('Other') // No explicit item_type column
      expect(result.data[1].notes).toBe('r-value 4.5')
      expect(result.data[2].item_type).toBe('Other') // No explicit item_type column
      expect(result.data[2].notes).toBe('titanium construction')
    })
  })

  describe('validateGearItems', () => {
    it('should validate correct items', () => {
      const items = [
        {
          description: 'Tent',
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        },
        {
          description: 'Water Bottle',
          weight_g: 150,
          item_type: 'Water',
          consumable: false,
          price: 25.99
        }
      ]

      const result = validateGearItems(items)

      expect(result.valid).toHaveLength(2)
      expect(result.invalid).toHaveLength(0)
    })

    it('should catch validation errors', () => {
      const items = [
        {
          description: 'A', // Too short
          weight_g: 0, // Invalid weight
          item_type: 'Shelter',
          consumable: false
        },
        {
          description: 'Heavy Item',
          weight_g: 100000, // Too heavy
          item_type: 'Other',
          consumable: false,
          price: -10 // Negative price
        }
      ]

      const result = validateGearItems(items)

      expect(result.valid).toHaveLength(0)
      expect(result.invalid).toHaveLength(2)

      // Check specific validation errors
      const firstItemErrors = result.invalid[0].errors
      expect(firstItemErrors).toContain('Description must be at least 2 characters')
      expect(firstItemErrors).toContain('Weight must be greater than 0')

      const secondItemErrors = result.invalid[1].errors
      expect(secondItemErrors).toContain('Weight seems unrealistically high (over 50kg)')
      expect(secondItemErrors).toContain('Price cannot be negative')
    })

    it('should handle edge cases', () => {
      const items = [
        {
          description: 'Valid Item',
          weight_g: 100,
          item_type: 'Other',
          consumable: false,
          price: 0 // Zero price should be valid
        }
      ]

      const result = validateGearItems(items)

      expect(result.valid).toHaveLength(1)
      expect(result.invalid).toHaveLength(0)
    })
  })

  describe('checkForDuplicates', () => {
    it('should identify exact duplicates', () => {
      const items = [
        {
          description: 'Tent',
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        },
        {
          description: 'Tent', // Exact duplicate
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        },
        {
          description: 'Sleeping Bag',
          weight_g: 800,
          item_type: 'Sleep',
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(2)
      expect(result.duplicates).toHaveLength(1)
      expect(result.warnings).toContain('Found 1 potential duplicate (similar description/weight/brand)')
      expect(result.duplicates[0].duplicateOf).toBe(0) // Duplicate of first item
    })

    it('should identify duplicates with similar weights', () => {
      const items = [
        {
          description: 'Water Bottle',
          weight_g: 150,
          item_type: 'Water',
          consumable: false
        },
        {
          description: 'Water Bottle', // Similar weight (within 5g tolerance)
          weight_g: 153,
          item_type: 'Water',
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(1)
      expect(result.duplicates).toHaveLength(1)
    })

    it('should not consider items with different weights as duplicates', () => {
      const items = [
        {
          description: 'Water Bottle',
          weight_g: 150,
          item_type: 'Water',
          consumable: false
        },
        {
          description: 'Water Bottle', // Different weight (>5g difference)
          weight_g: 200,
          item_type: 'Water',
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(2)
      expect(result.duplicates).toHaveLength(0)
    })

    it('should consider case-insensitive name matching', () => {
      const items = [
        {
          description: 'Tent',
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        },
        {
          description: 'TENT', // Same description, different case
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(1)
      expect(result.duplicates).toHaveLength(1)
    })

    it('should handle brand matching for duplicates', () => {
      const items = [
        {
          description: 'Tent',
          brand: 'Zpacks',
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        },
        {
          description: 'Tent',
          brand: 'MSR', // Different brand
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        },
        {
          description: 'Tent',
          brand: 'Zpacks', // Same brand - should be duplicate
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(2) // Zpacks and MSR tents
      expect(result.duplicates).toHaveLength(1) // Second Zpacks tent
    })

    it('should handle items without brands', () => {
      const items = [
        {
          description: 'Water Bottle',
          weight_g: 150,
          item_type: 'Water',
          consumable: false
        },
        {
          description: 'Water Bottle', // No brand on either - should be duplicate
          weight_g: 150,
          item_type: 'Water',
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(1)
      expect(result.duplicates).toHaveLength(1)
    })

    it('should handle multiple duplicates correctly', () => {
      const items = [
        {
          description: 'Energy Bar',
          weight_g: 50,
          item_type: 'Food',
          consumable: true
        },
        {
          description: 'Energy Bar',
          weight_g: 50,
          item_type: 'Food',
          consumable: true
        },
        {
          description: 'Energy Bar',
          weight_g: 50,
          item_type: 'Food',
          consumable: true
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(1)
      expect(result.duplicates).toHaveLength(2)
      expect(result.warnings).toContain('Found 2 potential duplicates (similar description/weight/brand)')
    })

    it('should return no duplicates for unique items', () => {
      const items = [
        {
          description: 'Tent',
          weight_g: 1200,
          item_type: 'Shelter',
          consumable: false
        },
        {
          description: 'Sleeping Bag',
          weight_g: 800,
          item_type: 'Sleep',
          consumable: false
        },
        {
          description: 'Stove',
          weight_g: 200,
          item_type: 'Cook',
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(3)
      expect(result.duplicates).toHaveLength(0)
      expect(result.warnings).toHaveLength(0)
    })
  })
})

