import { describe, it, expect } from 'vitest'
import { readFileSync } from 'fs'
import { join } from 'path'
import { parseCsv } from './csv'
import { validateGearItems, checkForDuplicates } from './index'

describe('CSV Parser - Real LighterPack Examples', () => {
  const examplesPath = join(process.cwd(), 'tests/examples/lighterpack/csv')

  describe('Trail Running CSV', () => {
    it('should parse trail-running.csv correctly', () => {
      const csvContent = readFileSync(join(examplesPath, 'trail-running.csv'), 'utf-8')
      const result = parseCsv(csvContent)

      expect(result.success).toBe(true)
      expect(result.errors).toHaveLength(0)
      expect(result.data.length).toBeGreaterThan(0)

      // Check specific items
      const hydrationVest = result.data.find(item => item.description === 'Hydration Vest')
      expect(hydrationVest).toBeDefined()
      expect(hydrationVest?.weight_g).toBe(250)
      expect(hydrationVest?.item_type).toBe('🎒 Pack')
      // Brand detection removed - parser preserves original data
      expect(hydrationVest?.brand).toBe(null)
      expect(hydrationVest?.notes).toContain('Ultimate Direction Ultra Vest 6.0')

      const hikingPoles = result.data.find(item => item.description === 'Hiking Poles')
      expect(hikingPoles).toBeDefined()
      expect(hikingPoles?.weight_g).toBe(275)
      expect(hikingPoles?.brand).toBe('Black Diamond')
    })

    it('should validate all items from trail-running.csv', () => {
      const csvContent = readFileSync(join(examplesPath, 'trail-running.csv'), 'utf-8')
      const result = parseCsv(csvContent)
      const validation = validateGearItems(result.data)

      expect(validation.invalid).toHaveLength(0)
      expect(validation.valid.length).toBe(result.data.length)
    })
  })

  describe('Four Pass Loop CSV', () => {
    it('should parse four-pass-loop.csv correctly', () => {
      const csvContent = readFileSync(join(examplesPath, 'four-pass-loop.csv'), 'utf-8')
      const result = parseCsv(csvContent)

      expect(result.success).toBe(true)
      expect(result.errors).toHaveLength(0)
      expect(result.data.length).toBeGreaterThan(20)

      // Check category diversity
      const categories = new Set(result.data.map(item => item.item_type))
      expect(categories.size).toBeGreaterThan(5)

      // Check specific item with URL and price
      const backpack = result.data.find(item => item.description === 'Backpack')
      expect(backpack).toBeDefined()
      expect(backpack?.weight_g).toBe(1960)
      expect(backpack?.price).toBe(315)
      // Brand detection removed - parser preserves original data
      expect(backpack?.brand).toBe(null)

      // Check sleeping system items
      const sleepingBag = result.data.find(item => item.description === 'Sleeping Bag')
      expect(sleepingBag).toBeDefined()
      expect(sleepingBag?.item_type).toBe('🛌 Sleep System')
      expect(sleepingBag?.weight_g).toBe(500)
    })

    it('should handle duplicates in four-pass-loop.csv', () => {
      const csvContent = readFileSync(join(examplesPath, 'four-pass-loop.csv'), 'utf-8')
      const result = parseCsv(csvContent)
      const duplicateCheck = checkForDuplicates(result.data)

      // Check that similar items (like multiple socks) are not marked as duplicates
      expect(duplicateCheck.unique.length).toBeGreaterThan(0)

      // Categories should be preserved
      const categories = new Set(duplicateCheck.unique.map(item => item.item_type))
      expect(categories).toContain('🎒 Pack')
      expect(categories).toContain('🛌 Sleep System')
      expect(categories).toContain('💧 Hydration')
    })
  })

  describe('JMT Loadout CSV', () => {
    it('should parse jmt-loadout.csv correctly', () => {
      const csvContent = readFileSync(join(examplesPath, 'jmt-loadout.csv'), 'utf-8')
      const result = parseCsv(csvContent)

      expect(result.success).toBe(true)
      expect(result.errors).toHaveLength(0)
      expect(result.data.length).toBeGreaterThan(30)

      // Check multiple quantity items
      const buff = result.data.find(item => item.description === 'Buff')
      expect(buff).toBeDefined()

      // Check brand extraction from desc field
      const campShirt = result.data.find(item => item.description === 'Camp Shirt')
      expect(campShirt).toBeDefined()
      // Brand detection removed - parser preserves original data
      expect(campShirt?.brand).toBe(null)
      expect(campShirt?.notes).toContain('Smartwool Classic All-Season')

      // Check item with comma in label
      const spareSocks = result.data.find(item => item.description?.includes('Hiking Socks, Spare'))
      expect(spareSocks).toBeDefined()
    })

    it('should extract all brands from jmt-loadout.csv', () => {
      const csvContent = readFileSync(join(examplesPath, 'jmt-loadout.csv'), 'utf-8')
      const result = parseCsv(csvContent)

      // Brand detection removed - parser preserves original data
      const itemsWithBrands = result.data.filter(item => item.brand)
      expect(itemsWithBrands.length).toBe(0) // No automatic brand detection
      const brands = new Set(result.data.map(item => item.brand).filter(Boolean))
      expect(brands).toContain('Patagonia')
      expect(brands).toContain('Smartwool')
      expect(brands).toContain('Salomon')
    })

    it('should handle consumable flags in jmt-loadout.csv', () => {
      const csvContent = readFileSync(join(examplesPath, 'jmt-loadout.csv'), 'utf-8')
      const result = parseCsv(csvContent)

      // Check consumable items
      const consumableItems = result.data.filter(item => item.consumable)

      // Most items should not be consumable in a gear list
      expect(consumableItems.length).toBeLessThan(result.data.length / 2)
    })
  })

  describe('Cross-file analysis', () => {
    it('should handle all three CSV files without errors', () => {
      const files = ['trail-running.csv', 'four-pass-loop.csv', 'jmt-loadout.csv']

      files.forEach(filename => {
        const csvContent = readFileSync(join(examplesPath, filename), 'utf-8')
        const result = parseCsv(csvContent)

        expect(result.success).toBe(true)
        expect(result.data.length).toBeGreaterThan(0)

        // All items should have required fields
        result.data.forEach(item => {
          expect(item.description).toBeTruthy()
          expect(item.weight_g).toBeGreaterThan(0)
          expect(item.item_type).toBeTruthy()
          expect(typeof item.consumable).toBe('boolean')
        })
      })
    })

    it('should preserve emoji categories from all files', () => {
      const files = ['trail-running.csv', 'four-pass-loop.csv', 'jmt-loadout.csv']
      const allCategories = new Set<string>()

      files.forEach(filename => {
        const csvContent = readFileSync(join(examplesPath, filename), 'utf-8')
        const result = parseCsv(csvContent)
        result.data.forEach(item => allCategories.add(item.item_type))
      })

      // Should preserve emoji categories
      expect(Array.from(allCategories).some(cat => cat.includes('🎒'))).toBe(true)
      expect(Array.from(allCategories).some(cat => cat.includes('🥋'))).toBe(true)
      expect(Array.from(allCategories).some(cat => cat.includes('💧'))).toBe(true)
    })
  })
})

