import { CollectionCompactRow, type CompactRowAction } from '@/components/shared/CollectionCompactRow'
import { Edit2, Trash2, Copy } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

interface GearCompactRowProps {
  item: GearItem
  weightUnit: WeightUnit
  onEdit: (item: GearItem) => void
  onDelete: (item: GearItem) => void
  onDuplicate?: (item: Omit<GearItem, 'id' | 'created_at' | 'updated_at' | 'user_id'>) => void
  onClick?: (item: GearItem) => void
}

export function GearCompactRow({ 
  item, 
  weightUnit, 
  onEdit, 
  onDelete,
  onDuplicate,
  onClick 
}: GearCompactRowProps) {
  // Build subtitle from brand, model, and description (matches the screenshot format)
  const subtitle = [item.brand, item.model, item.description]
    .filter(Boolean)
    .join(', ')

  // Category badge
  const categoryBadge = (
    <Badge variant="outline" className="text-xs px-2 py-0">
      {item.item_type}
    </Badge>
  )

  // Properties badges (compact version)
  const properties = (
    <div className="flex gap-1">
      {item.consumable && (
        <span className="text-xs text-muted-foreground">Consumable</span>
      )}
    </div>
  )

  // Data columns for compact view: Category, Weight, Qty, Total, Properties
  const totalWeight = item.weight_g
  const columns = [
    categoryBadge, // Category
    formatWeightWithUnit(item.weight_g, weightUnit), // Weight
    1, // Qty  
    formatWeightWithUnit(totalWeight, weightUnit), // Total
    properties // Properties (Worn/Consumable)
  ]

  // Build actions
  const actions: CompactRowAction[] = [
    {
      label: 'Edit',
      icon: <Edit2 className="mr-2 h-4 w-4" />,
      onClick: () => onEdit(item)
    },
    ...(onDuplicate ? [{
      label: 'Duplicate',
      icon: <Copy className="mr-2 h-4 w-4" />,
      onClick: () => {
        const { id, created_at, updated_at, user_id, ...cloneData } = item
        const newItem = { ...cloneData, description: `${cloneData.description || 'Item'} (Copy)` }
        onDuplicate(newItem)
      }
    }] : []),
    {
      label: 'Delete',
      icon: <Trash2 className="mr-2 h-4 w-4" />,
      onClick: () => onDelete(item),
      variant: 'destructive' as const
    }
  ]

  return (
    <CollectionCompactRow
      title={item.description || 'Untitled Item'}
      subtitle={subtitle}
      columns={columns}
      actions={actions}
      onClick={onClick ? () => onClick(item) : undefined}
      url={item.url || undefined}
    />
  )
}

