import { CollectionRow, type RowAction, type RowBadge } from '@/components/shared/CollectionRow'
import { Edit2, Trash2, Copy } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

interface GearRowProps {
  item: GearItem
  weightUnit: WeightUnit
  onEdit: (item: GearItem) => void
  onDelete: (item: GearItem) => void
  onDuplicate?: (item: Omit<GearItem, 'id' | 'created_at' | 'updated_at' | 'user_id'>) => void
  onClick?: (item: GearItem) => void
  showProperties?: boolean // Whether to show the Properties column
}

export function GearRow({ 
  item, 
  weightUnit, 
  onEdit, 
  onDelete,
  onDuplicate,
  onClick,
  showProperties = true
}: GearRowProps) {
  // Build subtitle from model/description
  const subtitle = [item.model, item.description]
    .filter(Boolean)
    .join(' • ')

  // Note: No category column for gear items - item_type is shown inline on mobile only

  // Build metadata for mobile
  const weightDisplay = formatWeightWithUnit(item.weight_g, weightUnit)
  const metadata = weightDisplay

  // Build secondary info for desktop columns (Weight, Properties?)
  const baseSecondaryInfo = [
    formatWeightWithUnit(item.weight_g, weightUnit)
  ]

  const propertiesColumn = (
    <div className="flex items-center gap-1">
      {item.consumable && (
        <Badge variant="secondary" className="text-xs">
          Consumable
        </Badge>
      )}
    </div>
  )

  const secondaryInfo = showProperties 
    ? [...baseSecondaryInfo, propertiesColumn]
    : baseSecondaryInfo

  const columnClasses = showProperties 
    ? ['text-right', '']
    : ['text-right']

  // Build actions
  const actions: RowAction[] = [
    {
      label: 'Edit',
      icon: <Edit2 className="h-4 w-4" />,
      onClick: () => onEdit(item)
    },
    ...(onDuplicate ? [{
      label: 'Duplicate',
      icon: <Copy className="h-4 w-4" />,
      onClick: () => {
        const { id, created_at, updated_at, user_id, ...cloneData } = item
        const newItem = { ...cloneData, description: `${cloneData.description || 'Item'} (Copy)` }
        onDuplicate(newItem)
      }
    }] : []),
    {
      label: 'Delete',
      icon: <Trash2 className="h-4 w-4" />,
      onClick: () => onDelete(item),
      variant: 'destructive',
      separator: true
    }
  ]

  return (
    <CollectionRow
      title={item.description || 'Untitled Item'}
      subtitle={subtitle}
      brand={item.brand || undefined}
      metadata={metadata}
      secondaryInfo={secondaryInfo}
      columnClasses={columnClasses}
      actions={actions}
      onClick={onClick ? () => onClick(item) : undefined}
      url={item.url || undefined}
    />
  )
}

